parameters.snippet:
def stage(name, fn, budget, uhr):
    start = uhr()
    try:
        wert = fn()
    except ValueError:
        return {"status": "fehler", "grund": name}
    dauer = uhr() - start
    if dauer > budget:
        return {"status": "timeout", "grund": name}
    return {"status": "ok", "wert": wert}

def ok_fn():
    return 7

def kaputt_fn():
    raise ValueError("daten weg")

def langsam_fn():
    return 1

uhr = iter([0, 40, 100, 100, 200])
a = stage("laden", ok_fn, 50, uhr.__next__)
b = stage("rechnen", kaputt_fn, 50, uhr.__next__)
c = stage("speichern", langsam_fn, 50, uhr.__next__)
status_zeile = a["status"] + " " + b["status"] + " " + c["status"]
summe = a.get("wert", 0) + b.get("wert", 0) + c.get("wert", 0)

